def calculate_black_area(A: int, B: int, C: int, D: int) -> int:
    def black_area_in_row(x1, x2, y):
        # Calculate black area in a row from x1 to x2 at y
        if y % 2 == 0:
            # Even row
            return (x2 - x1 + 1) // 2
        else:
            # Odd row
            return (x2 - x1) // 2 + (x1 % 2)

    total_black_area = 0
    for y in range(B, D):
        total_black_area += black_area_in_row(A, C - 1, y)

    return 2 * total_black_area
